"""Use a chosen coordinate frame to prove the seven remaining exercise claims in XI §2."""
import argparse
import json

from coordinate_figures import picture
from coordinate_positions import lesson
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/coordinate-proof-method.json'


def card(n,*,frames,cases,**data):
    pages=[259] if n==1038 else [259,260] if n==1039 else [260]
    item=lesson(n,pages=pages,frames=frames,cases=cases,**data)
    item['review']['reviewer']='Условия, числа и расположение материала в XI §2 сверены с печатными с. 259–260 издания 2023 года. Авторские доказательства и независимые координатные модели охватывают предельные положения, оба направления требуемого утверждения и новые примеры.'
    return item


def right_triangle():
    def triangle(label,b,a,edges,marks=()):
        return picture(label,{'A':(0,b),'B':(a,0),'M':(a/2,b/2)},edges,marks)
    initial=triangle('Прямоугольный треугольник с серединой M',4,6,'OA OB AB',['AOB']);halves=triangle('Две половины гипотенузы',4,6,'AM MB OM OA OB',['AOB']);spokes=triangle('Три равных расстояния',4,6,'OM MA MB');fresh=triangle('Новый треугольник 6×8',6,8,'OA OB AB OM',['AOB'])
    e=card(1038,question='Докажи, что середина гипотенузы прямоугольного треугольника равноудалена от всех трёх вершин. Построй удобные оси и поясни, почему доказательство охватывает любой прямоугольный треугольник.',
        answer='Поставь вершину прямого угла C в начало координат, а катеты направь вдоль осей. Если B=(a;0), A=(0;b), то середина AB есть M=(a/2;b/2). У путей M к A, B и C горизонтальная и вертикальная проекции отличаются только знаками. Все три квадрата расстояний равны (a²+b²)/4.',
        hint='Поставь координатные оси вдоль перпендикулярных катетов. Найди середину один раз, затем сравни абсолютные величины компонент до каждой вершины.',
        steps=[('Выбери координаты','В любой невырожденной прямоугольной фигуре можно провести оси вдоль катетов. На рисунке C совпала с O. Тогда C=(0;0), A=(0;b), B=(a;0), где a,b>0 произвольны.','Поворот и перенос осей не меняют расстояний между вершинами.'),
               ('Поставь середину','M=(a/2;b/2). По определению MA=MB. Чтобы проверить и MC, сравни пути от M к C и от M к A: обе горизонтальные составляющие равны −a/2, а вертикальные противоположны и равны по модулю b/2.','Квадраты противоположных чисел одинаковы.'),
               ('Выведи единую длину','Для каждого отрезка получили квадрат (a²+b²)/4, поэтому MA=MB=MC=√(a²+b²)/2. Если A=(0;6), B=(8;0), то гипотенуза равна 10, а общая длина 5.','Сравнение квадратов неотрицательных расстояний доказывает требуемое равенство.')],
        frames=[initial,initial,halves,spokes],cases=[initial,spokes,fresh],prompts=[('При B=(6;0), A=(0;4) найди абсциссу M.','3','Абсциссы концов гипотенузы 6 и 0; усредни их.'),('Чему равно MC при катетах 6 и 8?','5','Решение даёт половину гипотенузы длины 10.')])
    for name,label in e['visualization']['model']['labels'].items():
        if label=='O':e['visualization']['model']['labels'][name]='C=O'
    e['answer']['prompt']='Запиши, как выбранные координаты доказывают сразу три равных расстояния.'
    return e


def parallelogram_law():
    def model(label,a,p,q,edges):return picture(label,{'A':(-a,0),'C':(a,0),'B':(p,q),'D':(-p,-q)},edges)
    sides=model('Четыре стороны',3,1,2,'AB BC CD DA');pairs=model('Две пары равных сторон',3,1,2,'AB BC CD DA AC');diag=model('Обе диагонали через O',3,1,2,'AB BC CD DA AC BD');fresh=model('Другая пара диагоналей',2,-1,3,'AB BC CD DA AC BD')
    e=card(1039,question='Докажи, что сумма квадратов четырёх сторон параллелограмма равна сумме квадратов его двух диагоналей. Почему удобно поместить начало координат в точку пересечения диагоналей?',
        answer='Возьми A=(−a;0), C=(a;0) и B=(p;q), D=(−p;−q): диагонали делятся пополам. Квадраты двух соседних сторон равны (p+a)²+q² и (a−p)²+q². Сумма квадратов всех сторон равна 4(a²+p²+q²). У диагоналей квадраты 4a² и 4(p²+q²), их сумма совпадает.',
        hint='В центре параллелограмма координаты противоположных вершин меняют знаки. Сгруппируй равные противоположные стороны до раскрытия скобок.',
        steps=[('Задай вершины через центр','Проведи ось x вдоль AC и назови её половину a. Пара A,C имеет противоположные абсциссы. Вторая диагональ проходит через тот же центр, значит если B=(p;q), то D=(−p;−q).','Точка пересечения диагоналей параллелограмма делит каждую из них пополам.'),
               ('Сложи квадраты сторон','AB²=(p+a)²+q², BC²=(a−p)²+q². Есть по две стороны каждой длины. В сумме квадратов выражения +2ap и −2ap сокращаются, остаётся 4(a²+p²+q²).','При сравнении длин достаточно рассматривать одну сторону из каждой равной пары.'),
               ('Сравни диагонали','AC²=4a²; BD²=(2p)²+(2q)². Совпавшие суммы доказывают утверждение для произвольных p,q и a>0. На модели a=3,p=1,q=2 обе суммы 56.','Тождество доказано вычислением для всех разрешённых координат, числовой рисунок позволяет его проверить.')],
        frames=[sides,sides,pairs,diag],cases=[pairs,diag,fresh],prompts=[('В исходной схеме a=3,p=1,q=2. Чему равен BD²?','20','Вся вторая диагональ имеет смещение (2;4).'),('В новой схеме a=2,p=−1,q=3. Какова сумма квадратов диагоналей?','56','Вычисли 4·(4+1+9).')])
    e['answer']['prompt']='Выведи обе суммы через одни и те же координаты и объясни, где исчезают смешанные слагаемые.'
    return e


def medians():
    p={'A':(-2,0),'B':(2,0),'C':(0,8),'K':(-1,4),'L':(1,4)} # one grid square = 20 cm
    def iso(label,names,edges,marks=()):return picture(label,{k:p[k] for k in names},edges,marks)
    tri=iso('Данная медиана к основанию','ABC','AB AC CB OC',['AOC','BOC']);ends=iso('Середины боковых сторон','ABCKL','AB AC BC OC BK AL',['AOC','BOC']);left=iso('Медиана из B в середину AC','ABCK','AB AC CB BK');new=picture('Новый треугольник: основание 120 см, высота 160 см',{'A':(-3,0),'B':(3,0),'C':(0,8),'K':(-1.5,4),'L':(1.5,4)},'AB AC BC OC BK AL',['AOC','BOC'])
    q40=card(1040,unit='20 см',question='В равнобедренном треугольнике основание равно 80 см, а медиана к основанию — 160 см. Вычисли длины двух других медиан.',
        answer='Расположи основание от A=(−40;0) до B=(40;0), вершину C=(0;160). Середина AC равна K=(−20;80). У BK проекции 60 и 80, поэтому BK=100 см. Вторая медиана равна ей по симметрии. Обе имеют длину 100 см.',
        hint='Медиана, проведённая к основанию равнобедренного треугольника, является высотой. Для другой медианы конец ищи в середине боковой стороны.',
        steps=[('Построй треугольник','Половина основания равна 40 см. Помести его середину O в начало координат. A=(−40;0), B=(40;0), C=(0;160). Высота OC здесь совпадает с данной медианой.','Равенство боковых сторон задаёт ось симметрии CO.'),
               ('Найди концы двух медиан','Середина AC имеет координаты K=(−20;80), середина BC координаты L=(20;80). Медианы, которые надо найти, — BK и AL.','У каждой медианы конец находится на стороне, противоположной её начальной вершине.'),
               ('Измерь и используй симметрию','Из B к K смещение (−60;80). Поэтому BK=√(3600+6400)=100 см, а AL=BK по отражению относительно OC. В дополнительном примере с основанием 120 см горизонтальное смещение от нового B до K по модулю равно 90 см.','Отражение сохраняет длины и меняет местами вершины основания.')],
        frames=[tri,tri,ends,left],cases=[tri,ends,new],prompts=[('Для основания 80 см каков модуль горизонтальной проекции BK в сантиметрах?','60','Сравни абсциссы B=40 и K=−20.'),('Теперь основание 120 см. Каков модуль горизонтальной проекции BK?','90','B=(60;0), абсцисса середины AC равна −30; найди разность.')])
    q40['answer']={'mode':'exact','accepted':['100','100 см','100см','100;100','100; 100','100,0'],'prompt':'Введи длину каждой из двух равных медиан в сантиметрах.','feedback':'80 см — половина высоты, а горизонтальная составляющая искомой медианы равна 60 см. Объедини оба катета по Пифагору.'}
    pts={'A':(-5,0),'B':(2,0),'C':(0,5),'M':(1,2.5)} # scale 2 cm
    def sk(label,names,edges,marks=()):return picture(label,{k:pts[k] for k in names},edges,marks)
    begin=sk('Высота делит основание на 10 и 4 см','ABC','AB AC CB OC',['AOC','BOC']);short=sk('Сравни две боковые стороны','ABC','AB AC CB OC',['AOC','BOC']);segment=sk('Медиана к меньшей боковой стороне','ABCM','AB AC BC AM');fresh=picture('Новые отрезки основания 8 и 4 см',{'A':(-4,0),'B':(2,0),'C':(0,3),'M':(1,1.5)},'AB AC BC OC AM',['AOC','BOC'])
    q41=card(1041,unit='2 см',question='Высота треугольника равна 10 см. Она делит основание на отрезки 10 см и 4 см. Вычисли медиану к меньшей из двух других сторон.',
        answer='Возьми A=(−10;0), B=(4;0), C=(0;10). Из двух боковых сторон AC²=200, BC²=116, так что меньшая BC. Её середина M=(2;5). У медианы AM горизонтальная проекция 12, вертикальная 5, поэтому AM=13 см.',
        hint='Сначала сравни две стороны, каждая из которых является гипотенузой треугольника с общей высотой. Только затем выбирай вершину, из которой провести медиану.',
        steps=[('Назови нужную сторону','Для AC катеты 10 и 10, для BC — 4 и 10. Вторая гипотенуза короче, поскольку отличается лишь меньшим горизонтальным катетом.','При одинаковом одном катете большему второму катету соответствует большая гипотенуза.'),
               ('Отметь середину BC','У B=(4;0) и C=(0;10) середина M=(2;5). Медиана к BC выходит из A=(−10;0), а не из основания высоты O.','Чтобы выбрать начало медианы, возьми вершину вне стороны BC.'),
               ('Найди длину AM','Получаем горизонталь 2−(−10)=12 и вертикаль 5. Значит AM=√(144+25)=13 см. На новом рисунке AO=8, OB=4, CO=6, поэтому для той же медианы вертикальная проекция равна 3 см.','Положение точки M учитывает половины обеих координат концов боковой стороны.')],
        frames=[begin,short,segment,segment],cases=[short,segment,fresh],prompts=[('Какова горизонтальная проекция исходной медианы AM в сантиметрах?','12','Начало A имеет x=−10, конец M имеет x=2.'),('На новом рисунке высота равна 6 см. Какова вертикальная проекция AM в сантиметрах?','3','M — середина стороны с концами на высотах 0 и 6.')])
    q41['answer']={'mode':'exact','accepted':['13','13 см','13см','13,0','13.0'],'prompt':'Введи длину искомой медианы в сантиметрах.','feedback':'5 см — только вертикальная часть медианы. Проверь горизонтальную проекцию 12 см и возьми √(12²+5²).'}
    return [q40,q41]


def trapezoid():
    def frame(label,a,b,h,t,edges):
        p={'A':(-a,0),'D':(a,0),'B':(t-b,h),'C':(t+b,h)}
        return picture(label,p,edges)
    contour='AB BC CD DA';equal=frame('Середины оснований на одной вертикали',4,2,3,0,contour);left=frame('Сравни боковые стороны при сдвиге',4,2,3,1,contour);both=frame('Проверь две диагонали',4,2,3,0,contour+' AC BD');wide=frame('Второе основание длиннее первого',2,4,3,0,contour+' AC BD')
    e=card(1042,question='Докажи, что у равнобедренной трапеции диагонали равны. Сформулируй и докажи обратное утверждение, сохраняя исходное условие о трапеции.',
        answer='Для трапеции с различными основаниями равенство боковых сторон равносильно равенству диагоналей. Помести центр нижнего основания в начало координат и обозначь половины оснований a и b. Пусть t — горизонтальный сдвиг их середин. Разность квадратов боковых сторон равна 4t(a−b), разность квадратов диагоналей равна 4t(a+b). Так как a≠b и a+b>0, каждое из двух равенств эквивалентно t=0.',
        hint='Нужно доказать два направления. Попробуй связать каждое равенство с одним и тем же положением середин оснований.',
        steps=[('Запиши общую трапецию','Пусть нижнее основание A=(−a;0), D=(a;0), а верхнее B=(t−b;h), C=(t+b;h). Здесь a,b>0, a≠b, h>0. Параметр t показывает смещение середины верхнего основания от вертикали через O.','Две параллельные стороны трапеции не равны: равные параллельные противоположные стороны дали бы параллелограмм.'),
               ('Докажи прямое утверждение','AB²−CD²=(t+a−b)²−(t−a+b)²=4t(a−b). Равные боковые стороны и a≠b дают t=0. Тогда AC и BD имеют горизонтальные проекции одного модуля a+b и одинаковую разность высот. Диагонали равны.','При равных расстояниях равны их квадраты; одинаковые высоты сокращаются из разности квадратов.'),
               ('Докажи обратное','Если AC=BD, то 0=AC²−BD²=(t+a+b)²−(t−a−b)²=4t(a+b). Сумма a+b положительна, поэтому t=0, а значит AB=CD. Этот вывод работает независимо от того, какое основание длиннее.','После доказательства обеих импликаций для трапеций получен признак равнобедренности по диагоналям.')],
        frames=[equal,left,equal,both],cases=[left,both,wide],prompts=[('При a=4,b=2 и t=1 найди AB²−CD².','8','Воспользуйся формулой 4t(a−b).'),('При a=2,b=4 равенство диагоналей даёт 4t·6=0. Чему равен t?','0','Положительный множитель 24 отличен от нуля.')])
    e['answer']['prompt']='Сформулируй прямое и обратное утверждения, затем обоснуй каждое.'
    return e


def rectangle_test():
    def parallelogram(label,u,h,edges,marks=()):
        pos={'B':(4,0),'C':(4+u,h),'D':(u,h)}
        return picture(label,pos,edges,marks)
    border='OB BC CD DO';tilt=parallelogram('Наклонная фигура',2,3,border+' OC BD');rect=parallelogram('Равные диагонали',0,3,border+' OC BD',['BOD']);reverse=parallelogram('Сдвиг влево',-1,3,border+' OC BD');fresh=parallelogram('Другой прямоугольник',0,5,border+' OC BD',['BOD'])
    e=card(1043,question='В параллелограмме ABCD диагонали имеют равную длину. Докажи, что ABCD является прямоугольником. Объясни, где в рассуждении использовано условие параллелограмма.',
        answer='Выберем A=(0;0), B=(a;0), D=(u;v). Параллельность и равенство сторон даёт C=(a+u;v). Тогда AC²−BD²=(a+u)²−(u−a)²=4au. По условию это ноль. Поскольку a>0, u=0; сторона AD вертикальна и перпендикулярна AB. Параллелограмм с прямым углом — прямоугольник.',
        hint='Положи сторону AB на горизонтальную ось. Докажи, что равные диагонали не позволяют вершине D отклониться от вертикали через A.',
        steps=[('Вырази четвёртую вершину','Вершина A совпала с O, B=(a;0), D=(u;v). Перенос AB из D приводит в C=(a+u;v). Для произвольного четырёхугольника эта связь могла бы исчезнуть.','Противоположные стороны параллелограмма задают одинаковые согласованно направленные перемещения.'),
               ('Сравни диагонали','AC²=(a+u)²+v², BD²=(u−a)²+v². При вычитании остаётся 4au. Например, a=4,u=2 даёт разность 32: наклон вправо сделал диагонали различными.','При равных диагоналях их квадраты равны, а общие слагаемые высоты сокращаются.'),
               ('Вернись к прямому углу','Из 4au=0 и a>0 следует u=0. Теперь D и A принадлежат одной вертикали, B и A одной горизонтали. Угол DAB прямой, что для параллелограмма достаточно.','Параллелограмм с одним прямым углом имеет четыре прямых угла.')],
        frames=[tilt,tilt,tilt,rect],cases=[tilt,rect,reverse,fresh],prompts=[('На наклонной схеме a=4, u=2. Чему равно AC²−BD²?','32','Подставь в 4au.'),('На новой схеме высота 5 и a=4. При равных диагоналях чему равна абсцисса вершины D?','0','Высота сокращается из разности, а множитель 4a ненулевой.')])
    for key,label in e['visualization']['model']['labels'].items():
        if label=='O':e['visualization']['model']['labels'][key]='A=O'
    e['answer']['prompt']='Выведи условие прямого угла из равенства диагоналей, используя свойство параллелограмма.'
    return e


def sums_everywhere():
    def placement(label,point,edges):
        pos={'B':(6,0),'C':(6,3),'D':(0,3)}
        coincide=point==(0,0)
        if not coincide:pos['M']=point
        if coincide:edges=edges.replace('OM','').replace('MO','').replace('M','O')
        return picture(label,pos,edges,['BOD','OBC','BCD','CDO'])
    sides='OB BC CD DO';inside=placement('Точка M внутри',(2,1),sides+' OM BM CM DM');outside=placement('M вне прямоугольника',(8,-2),sides+' OM BM CM DM');edge=placement('M на стороне',(4,0),sides+' OM BM CM DM');vertex=placement('M совпала с A',(0,0),sides+' OM BM CM DM')
    e=card(1044,question='Для прямоугольника ABCD и любой точки M плоскости докажи AM²+CM²=BM²+DM². Проверь, что доказательство подходит и для внешней точки, и для точки на границе.',
        answer='Расположи A=(0;0), B=(a;0), D=(0;b), C=(a;b), M=(x;y). AM²+CM²=x²+y²+(x−a)²+(y−b)², а BM²+DM²=(x−a)²+y²+x²+(y−b)². Одинаковые четыре слагаемых входят в обе суммы, поэтому равенство истинно для любых действительных x,y.',
        hint='Сложи квадраты расстояний к двум противоположным вершинам. Проверь, какие квадраты горизонтальных и вертикальных смещений действительно входят в каждую сумму.',
        steps=[('Выбери оси вдоль сторон','Положи A в начало координат, AB вдоль Ox и AD вдоль Oy. Стороны перпендикулярны, так что эта система прямоугольная. Пусть a,b>0, а координаты M произвольны.','Выбор удобных осей не меняет расстояний и не ограничивает положение M.'),
               ('Собери четыре слагаемых','Для A и C получаются квадраты x²,y²,(x−a)²,(y−b)². Для B и D возникают те же четыре выражения, только в другом порядке. Раскрывать квадраты не требуется.','Формула расстояния независимо учитывает горизонтальную и вертикальную составляющие.'),
               ('Проверь границы условия','Снаружи некоторые разности меняют знак, но равенство сумм квадратов остаётся. На стороне одна составляющая равна нулю. При M=A имеем AC²=AB²+AD² — теорему Пифагора для прямоугольника.','Доказательство не использует неравенства 0≤x≤a или 0≤y≤b.')],
        frames=[inside,inside,inside,outside],cases=[inside,outside,edge,vertex],prompts=[('При a=6,b=3 и M=(2;1) найди AM²+CM².','25','AM²=4+1, CM²=16+4. Сложи оба результата.'),('В новом положении M=A при a=6,b=3 чему равна общая сумма?','45','Остаётся квадрат диагонали 6²+3².')])
    for key,label in e['visualization']['model']['labels'].items():
        if label=='O':e['visualization']['model']['labels'][key]='A=M' if key.endswith('__v7') else 'A=O'
    e['answer']['prompt']='Запиши две суммы квадратов и объясни, почему положение M не ограничено.'
    return e


def build():
    return {'bookId':BOOK,'lessons':[right_triangle(),parallelogram_law()]+medians()+[trapezoid(),rectangle_test(),sums_everywhere()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true')
    text=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==text
    else:OUT.write_text(text)
